        sport=('The awards panel wants every player with at least 8 goals.', 'Return player id and goal_count for players with 8 or more goals across both seasons. Most goals first, then player id.', ['player_id', 'goal_count'], 'SELECT player_id, COUNT(*) AS goal_count\nFROM goals\nGROUP BY player_id\nHAVING COUNT(*) >= 8\nORDER BY goal_count DESC, player_id;'),
