        politics=('The commission wants the most contested seats of 2025.', 'For election 3, find constituencies with 7 or more candidates. Return constituency id and candidate_count, most first, then constituency id.', ['constituency_id', 'candidate_count'], 'SELECT constituency_id, COUNT(*) AS candidate_count\nFROM results\nWHERE election_id = 3\nGROUP BY constituency_id\nHAVING COUNT(*) >= 7\nORDER BY candidate_count DESC, constituency_id;'),
