              politics="SELECT CONCAT(c.first_name, ' ', c.last_name) AS candidate, r.votes\nFROM results r\nJOIN candidates c ON r.candidate_id = c.candidate_id\nWHERE r.election_id = 3 AND r.constituency_id = 1\nORDER BY r.votes DESC;",
