  dict(title='LEFT JOIN with COUNT: keep the zeros', level='Medium', visual='join-venn',
       explanation='COUNT(column) ignores NULLs, so rows with no partner show 0. COUNT(*) would wrongly show 1, because it counts the empty joined row.',
       tryIt='Replace the COUNT column with COUNT(*) and watch the zeros become ones.',
       v=dict(sales="SELECT c.customer_id, CONCAT(c.first_name, ' ', c.last_name) AS customer,\n       COUNT(o.order_id) AS num_orders\nFROM customers c\nLEFT JOIN orders o ON c.customer_id = o.customer_id\nGROUP BY c.customer_id, c.first_name, c.last_name\nORDER BY num_orders, c.customer_id;",
              sport='SELECT t.team_name, COUNT(p.player_id) AS players\nFROM teams t\nLEFT JOIN players p ON p.team_id = t.team_id\nGROUP BY t.team_id, t.team_name\nORDER BY players, t.team_name;',
              fashion='SELECT p.product_name, COUNT(l.line_id) AS times_sold\nFROM products p\nLEFT JOIN sale_lines l ON l.product_id = p.product_id\nGROUP BY p.product_id, p.product_name\nORDER BY times_sold, p.product_name\nLIMIT 15;',
              politics='SELECT p.party_name, COUNT(c.candidate_id) AS candidates\nFROM parties p\nLEFT JOIN candidates c ON c.party_id = p.party_id\nGROUP BY p.party_id, p.party_name\nORDER BY candidates DESC;',
              finance="SELECT c.customer_id, CONCAT(c.first_name, ' ', c.last_name) AS customer,\n       COUNT(l.loan_id) AS num_loans\nFROM customers c\nLEFT JOIN loans l ON l.customer_id = c.customer_id\nGROUP BY c.customer_id, c.first_name, c.last_name\nORDER BY num_loans, c.customer_id\nLIMIT 20;",
              healthcare="SELECT p.patient_id, CONCAT(p.first_name, ' ', p.last_name) AS patient,\n       COUNT(a.appointment_id) AS visits\nFROM patients p\nLEFT JOIN appointments a ON a.patient_id = p.patient_id\nGROUP BY p.patient_id, p.first_name, p.last_name\nORDER BY visits, p.patient_id\nLIMIT 20;")),
