              finance="SELECT r.due_date, r.amount_due, r.paid_date, CONCAT(c.first_name, ' ', c.last_name) AS borrower\nFROM repayments r\nJOIN loans l ON r.loan_id = l.loan_id\nJOIN customers c ON l.customer_id = c.customer_id\nWHERE l.loan_id = 1\nORDER BY r.due_date;",
