  dict(title='Join plus GROUP BY: totals by a looked-up name', level='Medium',
       explanation='Joins give you the labels, GROUP BY gives you the totals. Most business reports are exactly this combination.',
       tryIt='Change JOIN to LEFT JOIN on the first join and look for new rows.',
       v=dict(sales='SELECT cat.category_name,\n       SUM(oi.quantity) AS units_sold,\n       ROUND(SUM(oi.quantity * oi.unit_price * (1 - oi.discount)), 2) AS revenue\nFROM categories cat\nJOIN products p ON cat.category_id = p.category_id\nJOIN order_items oi ON p.product_id = oi.product_id\nGROUP BY cat.category_name\nORDER BY revenue DESC;',
              sport='SELECT t.team_name, COUNT(*) AS goals\nFROM goals g\nJOIN players p ON g.player_id = p.player_id\nJOIN teams t ON p.team_id = t.team_id\nGROUP BY t.team_name\nORDER BY goals DESC;',
              fashion='SELECT st.store_name,\n       COUNT(DISTINCT s.sale_id) AS sales,\n       ROUND(SUM(l.qty * l.unit_price * (1 - l.discount)), 2) AS revenue\nFROM stores st\nJOIN sales s ON st.store_id = s.store_id\nJOIN sale_lines l ON s.sale_id = l.sale_id\nGROUP BY st.store_name\nORDER BY revenue DESC;',
              politics='SELECT p.party_name, SUM(r.votes) AS votes\nFROM results r\nJOIN candidates c ON r.candidate_id = c.candidate_id\nJOIN parties p ON c.party_id = p.party_id\nWHERE r.election_id = 3\nGROUP BY p.party_name\nORDER BY votes DESC;',
              finance='SELECT b.branch_name, COUNT(*) AS loans, SUM(l.principal) AS total_lent\nFROM loans l\nJOIN customers c ON l.customer_id = c.customer_id\nJOIN branches b ON c.branch_id = b.branch_id\nGROUP BY b.branch_name\nORDER BY total_lent DESC;',
              healthcare="SELECT dp.department_name, COUNT(*) AS completed_visits\nFROM appointments a\nJOIN doctors d ON a.doctor_id = d.doctor_id\nJOIN departments dp ON d.department_id = dp.department_id\nWHERE a.status = 'Completed'\nGROUP BY dp.department_name\nORDER BY completed_visits DESC;")),
