        finance=('Lending wants customers to offer a first loan.', 'Find every customer who has never taken a loan. Return customer id, first name and last name, sorted by customer id.', ['customer_id', 'first_name', 'last_name'], 'SELECT c.customer_id, c.first_name, c.last_name\nFROM customers c\nLEFT JOIN loans l ON l.customer_id = c.customer_id\nWHERE l.loan_id IS NULL\nORDER BY c.customer_id;'),
